+        transition: transform 0.18s ease, box-shadow 0.18s ease;
+      }
+
+      button:hover {
+        transform: translateY(-1px);
+        box-shadow: 0 18px 36px rgba(37, 99, 235, 0.26);
+      }
+
+      button:focus-visible {
+        outline: 3px solid rgba(37, 99, 235, 0.28);
+        outline-offset: 3px;
+      }
+
+      .status {
+        margin: 14px 0 0;
+        min-height: 1.5em;
+        color: #0f766e;
+        font-weight: 600;
+      }
+
+      @media (max-width: 640px) {
+        .page {
