<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --card: rgba(255, 255, 255, 0.9);
        --border: #d9e2ef;
        --text: #172033;
        --muted: #5d6b82;
        --accent: #2563eb;
        --accent-dark: #1d4ed8;
        --error: #dc2626;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #e8f1ff 0, transparent 42%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px;
      }

      .contact-card {
        width: min(100%, 640px);
        background: var(--card);
        border: 1px solid rgba(217, 226, 239, 0.8);
        border-radius: 24px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(12px);
        padding: 32px;
      }

      .eyebrow {
        margin: 0 0 8px;
        font-size: 0.875rem;
        font-weight: 600;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--accent);
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 2.75rem);
        line-height: 1.1;
      }

      .subtitle {
        margin: 12px 0 0;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        margin-top: 28px;
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        border-radius: 14px;
        padding: 14px 16px;
        font: inherit;
        color: var(--text);
        background: #fff;
        transition: border-color 0.2s ease, box-shadow 0.2s ease;
      }

      input::placeholder {
        color: #94a3b8;
      }

      input:focus {
        outline: none;
        border-color: var(--accent);
        box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
      }

      .helper-text {
        margin: 0;
        font-size: 0.875rem;
        color: var(--muted);
      }

      .error-message {
        margin: 0;
        font-size: 0.875rem;
        color: var(--error);
        display: none;
      }

      .form-field.invalid input {
        border-color: var(--error);
        box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.1);
      }

      .form-field.invalid .error-message {
        display: block;
      }

      .actions {
        margin-top: 6px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 14px;
        padding: 14px 18px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
        cursor: pointer;
        box-shadow: 0 14px 30px rgba(37, 99, 235, 0.22);
        transition: transform 0.18s ease, box-shadow 0.18s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 36px rgba(37, 99, 235, 0.26);
      }

      button:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.28);
        outline-offset: 3px;
      }

      .status {
        margin: 14px 0 0;
        min-height: 1.5em;
        color: #0f766e;
        font-weight: 600;
      }

      @media (max-width: 640px) {
        .page {
          padding: 16px;
        }

        .contact-card {
          padding: 24px;
          border-radius: 20px;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="contact-card" aria-labelledby="support-title">
        <p class="eyebrow">Support</p>
        <h1 id="support-title">Contact our support team</h1>
        <p class="subtitle">
          Send us a message and we'll get back to you as soon as possible.
        </p>

        <form id="contact-form" novalidate>
          <div class="form-field" data-field="full-name">
            <label for="full-name">Full name</label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              placeholder="Jane Doe"
              required
            />
            <p class="error-message" id="full-name-error">Please enter your full name.</p>
          </div>

          <div class="form-field" data-field="email-address">
            <label for="email-address">Email address</label>
            <input
              id="email-address"
              name="email"
              type="email"
              autocomplete="email"
              placeholder="jane@example.com"
              required
            />
            <p class="error-message" id="email-address-error">Please enter a valid email address.</p>
          </div>

          <div class="form-field" data-field="phone-number">
            <label for="phone-number">Phone number</label>
            <input
              id="phone-number"
              name="phone"
              type="tel"
              autocomplete="tel"
              placeholder="(555) 123-4567"
            />
            <p class="helper-text">Format: +1 555 123 4567, (555) 123-4567, or similar.</p>
          </div>

          <div class="actions">
            <button type="submit">Send message</button>
          </div>

          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("contact-form");
      const status = document.getElementById("form-status");
      const fields = {
        fullName: document.querySelector('[data-field="full-name"]'),
        email: document.querySelector('[data-field="email-address"]'),
      };

      function setFieldState(fieldName, isValid) {
        fields[fieldName].classList.toggle("invalid", !isValid);
      }

      function validate() {
        const fullName = document.getElementById("full-name");
        const email = document.getElementById("email-address");
        const fullNameValid = fullName.value.trim().length > 0;
        const emailValid = email.validity.valid && email.value.trim().length > 0;

        setFieldState("fullName", fullNameValid);
        setFieldState("email", emailValid);

        return fullNameValid && emailValid;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        if (!validate()) {
          return;
        }

        status.textContent = "Thanks — your message has been prepared for submission.";
        form.reset();
        Object.values(fields).forEach((field) => field.classList.remove("invalid"));
      });

      ["full-name", "email-address"].forEach((id) => {
        const input = document.getElementById(id);
        input.addEventListener("input", () => {
          if (input.value.trim() === "") {
            document.querySelector(`[data-field="${id}"]`).classList.remove("invalid");
            return;
          }
          validate();
        });
      });
    </script>
  </body>
</html>
