    <script>
      const form = document.getElementById("contact-form");
      const status = document.getElementById("form-status");
      let hasSubmitted = false;
      const fields = {
        fullName: document.querySelector('[data-field="full-name"]'),
        email: document.querySelector('[data-field="email-address"]'),
      };

      function setFieldState(fieldName, isValid) {
        fields[fieldName].classList.toggle("invalid", !isValid);
      }

      function validate() {
        const fullName = document.getElementById("full-name");
        const email = document.getElementById("email-address");
        const fullNameValid = fullName.value.trim().length > 0;
        const emailValid = email.validity.valid && email.value.trim().length > 0;

        setFieldState("fullName", fullNameValid);
        setFieldState("email", emailValid);

        return fullNameValid && emailValid;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        hasSubmitted = true;
        status.textContent = "";

        if (!validate()) {
          return;
        }

        status.textContent = "Thanks — your message has been prepared for submission.";
        form.reset();
        hasSubmitted = false;
        Object.values(fields).forEach((field) => field.classList.remove("invalid"));
      });

      ["full-name", "email-address"].forEach((id) => {
        const input = document.getElementById(id);
        input.addEventListener("input", () => {
          if (!hasSubmitted) {
            return;
          }

          if (input.value.trim() === "") {
            document.querySelector(`[data-field="${id}"]`).classList.remove("invalid");
            return;
          }
          validate();
        });
      });
    </script>
